import{_ as t,o as a,c as o,V as c}from"./index-LONQbtYs.js";const r={},s={class:"legal-doc"};function i(b,e){return a(),o("div",s,[...e[0]||(e[0]=[c('<h1 data-v-5ebb4cc1>COOKIE POLICY</h1><p class="subtitle" data-v-5ebb4cc1><strong data-v-5ebb4cc1>Last updated</strong> April 05, 2026</p><p data-v-5ebb4cc1> This Cookie Policy explains how <strong data-v-5ebb4cc1>Aidan Boissonneault</strong> (&quot;Company,&quot; &quot;we,&quot; &quot;us,&quot; and &quot;our&quot;) uses cookies and similar technologies to recognize you when you visit our website at <a href="https://www.tervabrewed.com" target="_blank" rel="noopener noreferrer" data-v-5ebb4cc1>https://www.tervabrewed.com</a> (&quot;Website&quot;). It explains what these technologies are and why we use them, as well as your rights to control our use of them. </p><p data-v-5ebb4cc1> In some cases we may use cookies to collect personal information, or that becomes personal information if we combine it with other information. </p><h2 data-v-5ebb4cc1>What are cookies?</h2><p data-v-5ebb4cc1> Cookies are small data files that are placed on your computer or mobile device when you visit a website. Cookies are widely used by website owners in order to make their websites work, or to work more efficiently, as well as to provide reporting information. </p><p data-v-5ebb4cc1> Cookies set by the website owner (in this case, Aidan Boissonneault) are called &quot;first-party cookies.&quot; Cookies set by parties other than the website owner are called &quot;third-party cookies.&quot; Third-party cookies enable third-party features or functionality to be provided on or through the website (e.g., advertising, interactive content, and analytics). The parties that set these third-party cookies can recognize your computer both when it visits the website in question and also when it visits certain other websites. </p><h2 data-v-5ebb4cc1>Why do we use cookies?</h2><p data-v-5ebb4cc1> We use first-party cookies for technical reasons in order for our Website to operate. These are &quot;essential&quot; or &quot;strictly necessary&quot; cookies required to provide you with core services such as staying signed in across sessions. </p><h2 data-v-5ebb4cc1>How can I control cookies?</h2><p data-v-5ebb4cc1> You have the right to decide whether to accept or reject cookies. You can exercise your cookie rights by setting your preferences in the Cookie Preference Center. Essential cookies cannot be rejected as they are strictly necessary to provide you with services. </p><p data-v-5ebb4cc1> The Cookie Preference Center can be found in the notification banner and on our Website. If you choose to reject cookies, you may still use our Website though your access to some functionality and areas of our Website may be restricted. You may also set or amend your web browser controls to accept or refuse cookies. </p><p data-v-5ebb4cc1> The specific types of first-party cookies served through our Website and the purposes they perform are described in the table below: </p><h3 data-v-5ebb4cc1>Essential cookies</h3><p data-v-5ebb4cc1> These cookies are strictly necessary to provide you with services available through our Website and to use some of its features, such as access to secure areas. </p><div class="cookie-table" data-v-5ebb4cc1><table data-v-5ebb4cc1><tbody data-v-5ebb4cc1><tr data-v-5ebb4cc1><td class="label" data-v-5ebb4cc1>Name:</td><td class="value" data-v-5ebb4cc1>session_token</td></tr><tr data-v-5ebb4cc1><td class="label" data-v-5ebb4cc1>Purpose:</td><td class="value" data-v-5ebb4cc1> Stores the session token used to authenticate and maintain your login session. </td></tr><tr data-v-5ebb4cc1><td class="label" data-v-5ebb4cc1>Provider:</td><td class="value" data-v-5ebb4cc1>.tervabrewed.com</td></tr><tr data-v-5ebb4cc1><td class="label" data-v-5ebb4cc1>Service:</td><td class="value" data-v-5ebb4cc1>Better Auth (authentication)</td></tr><tr data-v-5ebb4cc1><td class="label" data-v-5ebb4cc1>Type:</td><td class="value" data-v-5ebb4cc1>http_cookie</td></tr><tr data-v-5ebb4cc1><td class="label" data-v-5ebb4cc1>Expires in:</td><td class="value" data-v-5ebb4cc1>Session</td></tr></tbody></table></div><div class="cookie-table" data-v-5ebb4cc1><table data-v-5ebb4cc1><tbody data-v-5ebb4cc1><tr data-v-5ebb4cc1><td class="label" data-v-5ebb4cc1>Name:</td><td class="value" data-v-5ebb4cc1>session_data</td></tr><tr data-v-5ebb4cc1><td class="label" data-v-5ebb4cc1>Purpose:</td><td class="value" data-v-5ebb4cc1> Stores cached session data to reduce server lookups and improve performance when cookie cache is enabled. </td></tr><tr data-v-5ebb4cc1><td class="label" data-v-5ebb4cc1>Provider:</td><td class="value" data-v-5ebb4cc1>.tervabrewed.com</td></tr><tr data-v-5ebb4cc1><td class="label" data-v-5ebb4cc1>Service:</td><td class="value" data-v-5ebb4cc1>Better Auth (authentication)</td></tr><tr data-v-5ebb4cc1><td class="label" data-v-5ebb4cc1>Type:</td><td class="value" data-v-5ebb4cc1>http_cookie</td></tr><tr data-v-5ebb4cc1><td class="label" data-v-5ebb4cc1>Expires in:</td><td class="value" data-v-5ebb4cc1>Session</td></tr></tbody></table></div><div class="cookie-table" data-v-5ebb4cc1><table data-v-5ebb4cc1><tbody data-v-5ebb4cc1><tr data-v-5ebb4cc1><td class="label" data-v-5ebb4cc1>Name:</td><td class="value" data-v-5ebb4cc1>dont_remember</td></tr><tr data-v-5ebb4cc1><td class="label" data-v-5ebb4cc1>Purpose:</td><td class="value" data-v-5ebb4cc1> Stores a flag indicating that the user opted out of the &quot;remember me&quot; feature, ensuring their session is not persisted beyond the current browser session. </td></tr><tr data-v-5ebb4cc1><td class="label" data-v-5ebb4cc1>Provider:</td><td class="value" data-v-5ebb4cc1>.tervabrewed.com</td></tr><tr data-v-5ebb4cc1><td class="label" data-v-5ebb4cc1>Service:</td><td class="value" data-v-5ebb4cc1>Better Auth (authentication)</td></tr><tr data-v-5ebb4cc1><td class="label" data-v-5ebb4cc1>Type:</td><td class="value" data-v-5ebb4cc1>http_cookie</td></tr><tr data-v-5ebb4cc1><td class="label" data-v-5ebb4cc1>Expires in:</td><td class="value" data-v-5ebb4cc1>Session</td></tr></tbody></table></div><h2 data-v-5ebb4cc1>How can I control cookies on my browser?</h2><p data-v-5ebb4cc1> As the means by which you can refuse cookies through your web browser controls vary from browser to browser, you should visit your browser&#39;s help menu for more information. The following is information about how to manage cookies on the most popular browsers: </p><ul data-v-5ebb4cc1><li data-v-5ebb4cc1><a href="https://support.google.com/chrome/answer/95647#zippy=%2Callow-or-block-cookies" target="_blank" rel="noopener noreferrer" data-v-5ebb4cc1>Chrome</a></li><li data-v-5ebb4cc1><a href="https://support.microsoft.com/en-us/windows/delete-and-manage-cookies-168dab11-0753-043d-7c16-ede5947fc64d" target="_blank" rel="noopener noreferrer" data-v-5ebb4cc1>Internet Explorer</a></li><li data-v-5ebb4cc1><a href="https://support.mozilla.org/en-US/kb/enhanced-tracking-protection-firefox-desktop?redirectslug=enable-and-disable-cookies-website-preferences&amp;redirectlocale=en-US" target="_blank" rel="noopener noreferrer" data-v-5ebb4cc1>Firefox</a></li><li data-v-5ebb4cc1><a href="https://support.apple.com/en-ie/guide/safari/sfri11471/mac" target="_blank" rel="noopener noreferrer" data-v-5ebb4cc1>Safari</a></li><li data-v-5ebb4cc1><a href="https://support.microsoft.com/en-us/windows/microsoft-edge-browsing-data-and-privacy-bb8174ba-9d73-dcf2-9b4a-c582b4e640dd" target="_blank" rel="noopener noreferrer" data-v-5ebb4cc1>Edge</a></li><li data-v-5ebb4cc1><a href="https://help.opera.com/en/latest/web-preferences/" target="_blank" rel="noopener noreferrer" data-v-5ebb4cc1>Opera</a></li></ul><h2 data-v-5ebb4cc1>What about other tracking technologies, like web beacons?</h2><p data-v-5ebb4cc1> Cookies are not the only way to recognize or track visitors to a website. We may use other, similar technologies from time to time, like web beacons (sometimes called &quot;tracking pixels&quot; or &quot;clear gifs&quot;). These are tiny graphics files that contain a unique identifier that enables us to recognize when someone has visited our Website or opened an email including them. In many instances, these technologies are reliant on cookies to function properly, and so declining cookies will impair their functioning. </p><h2 data-v-5ebb4cc1>Do you serve targeted advertising?</h2><p data-v-5ebb4cc1> We do not serve targeted advertising through our Website and do not use cookies for advertising purposes. </p><h2 data-v-5ebb4cc1>How often will you update this Cookie Policy?</h2><p data-v-5ebb4cc1> We may update this Cookie Policy from time to time in order to reflect, for example, changes to the cookies we use or for other operational, legal, or regulatory reasons. Please therefore revisit this Cookie Policy regularly to stay informed about our use of cookies and related technologies. </p><p data-v-5ebb4cc1>The date at the top of this Cookie Policy indicates when it was last updated.</p><h2 data-v-5ebb4cc1>Where can I get further information?</h2><p data-v-5ebb4cc1> If you have any questions about our use of cookies or other technologies, please email us at <a href="mailto:tervabrewed@gmail.com" data-v-5ebb4cc1>tervabrewed@gmail.com</a> or by post to: </p><div class="contact-block" data-v-5ebb4cc1><p data-v-5ebb4cc1><strong data-v-5ebb4cc1>Aidan Boissonneault</strong></p><p data-v-5ebb4cc1>North Bay, Ontario</p><p data-v-5ebb4cc1>Canada</p></div><p class="generated-by" data-v-5ebb4cc1> This Cookie Policy was created using <a href="https://termly.io/products/cookie-consent-manager/" target="_blank" rel="noopener" data-v-5ebb4cc1>Termly&#39;s Cookie Consent Manager</a>. </p>',32)])])}const n=t(r,[["render",i],["__scopeId","data-v-5ebb4cc1"]]);export{n as default};
